"r_sourced":{"title":"𐌰𐌽𐌳𐌰𐍅𐌰𐌿𐍂𐌳 𐌼𐌹𐌸 𐍅𐌰𐌿𐍂𐌳𐌰𐌼 𐍆𐍂𐌿𐌼𐌹𐍃𐍄𐌰𐌹𐌼 (Perplexity)","desc":"Perplexity 𐌽𐌰𐍄𐌹 𐍃𐍉𐌺𐌴𐌹𐌸 𐌾𐌰𐌷 𐌼𐌹𐌸 𐍅𐌰𐌿𐍂𐌳𐌰𐌼 𐍆𐍂𐌿𐌼𐌹𐍃𐍄𐌰𐌹𐌼 𐌰𐌽𐌳𐌷𐌰𐍆𐌾𐌹𐌸; 𐌸𐌰𐌸𐍂𐍉𐌷 Claude 𐍅𐌰𐌿𐍂𐌳 𐌸𐌰𐍄𐌴𐌹 𐍅𐌰𐌿𐍂𐌳 𐍆𐍂𐌿𐌼𐌹𐍃𐍄 𐌽𐌹 𐌷𐌰𐌱𐌰𐌹𐌸 𐌰𐍄𐌰𐌿𐌲𐌾𐌹𐌸.","tip":"𐌲𐍉𐌸 𐌳𐌿 𐌸𐌰𐌹𐌼𐌴𐌹 𐌹𐌽𐌼𐌰𐌹𐌳𐌾𐌰𐌽𐌳: 𐍅𐌰𐌹𐍂𐌸𐌰, 𐌼𐌴𐌻𐌰 𐌿𐍃𐌻𐌿𐌺𐌰𐌽𐌳𐌴𐌹𐌽𐍃, 𐌽𐌹𐌿𐌾𐌰 𐍃𐍀𐌹𐌻𐌻𐌰. 𐌰𐌽𐌰 𐌸𐌰𐌼𐌼𐌰 𐌻𐌰𐌿𐍆𐌰 Claude 𐌹𐌽 𐍃𐍄𐌰𐌸 𐌹𐌶𐌴 𐍃𐍄𐌰𐌽𐌳𐌹𐌸. 𐌾𐌰𐌷 𐌽𐌹 𐍃𐍉𐌺𐌴𐌹𐌸, 𐌿𐍃𐍃𐌰𐌽𐌳𐌴𐌹 𐍅𐌰𐌿𐍂𐌳𐌰 𐍆𐍂𐌿𐌼𐌹𐍃𐍄𐌰 𐍃𐌰𐌹𐍈𐌰𐌽."},
